"""
Generates batches 02–23 of labeled tweet scoring examples.
Each batch: 100 examples (~35 ready, ~35 below_target, ~30 failed_floor).
Run: python data/raw/batch_generator.py
"""
import json
import sys
from pathlib import Path

_ROOT = Path(__file__).resolve().parent.parent.parent
sys.path.insert(0, str(_ROOT))

from dataset.schemas import RUBRIC_HASH, ScoreSet  # noqa: E402


def make(id, content, pillar, hook, tone, x_algo, data_s, pillar_s, cta, nvl, reasoning):
    scores = {
        "hook_strength": hook, "tone_compliance": tone,
        "x_algorithm_optimization": x_algo, "data_specificity": data_s,
        "pillar_alignment": pillar_s, "cta_quality": cta,
        "never_list_violation": nvl, "reasoning": reasoning,
    }
    ss = ScoreSet(**scores)
    tier = ss.tier()
    return {
        "id": id, "content": content, "pillar": pillar,
        "quality_tier": tier, "scores": scores, "rubric_hash": RUBRIC_HASH,
    }


